// Flux surveillés. Ajoute / retire des lignes librement : chaque URL produit
// un item, et le nœud « Lire le flux RSS » s'exécute une fois par item.
const FEEDS = [
  // Développement web & performance
  "https://nextjs.org/feed.xml",
  "https://web.dev/static/blog/feed.xml",
  "https://www.smashingmagazine.com/feed/",
  "https://css-tricks.com/feed/",

  // SEO & marketing digital
  "https://searchengineland.com/feed",
  "https://www.searchenginejournal.com/feed/",
  "https://www.abondance.com/feed",

  // Automatisation & IA
  "https://blog.n8n.io/rss/",
  "https://liora.io/feed",

  // Francophone / PME
  "https://www.blogdumoderateur.com/feed/",
"https://www.alsacreations.com/rss/actualites.xml",
"https://www.blogdumoderateur.com/feed/",
]

return FEEDS.map((feedUrl) => ({ json: { feedUrl } }))

// Sélectionne les sujets qui parlent VRAIMENT à l'audience du site :
// PME et entrepreneurs qui veulent un site qui convertit, du SEO, et de
// l'automatisation. Ajuste les poids ci-dessous, c'est le seul réglage qui
// change la qualité des sujets retenus.
const KEYWORDS = {
  // Cœur de cible : poids fort
  3: ["seo", "référencement", "referencement", "google search", "conversion",
      "taux de conversion", "landing page", "core web vitals", "vitesse",
      "performance web", "automatisation", "automation", "n8n", "workflow",
      "pme", "small business", "e-commerce", "ecommerce"],
  // Sujets techniques que je traite : poids moyen
  2: ["next.js", "nextjs", "react", "wordpress", "accessibilité", "accessibility",
      "ux", "design system", "responsive", "webflow", "cms", "headless",
      "analytics", "tracking", "schema.org", "structured data", "ia", "llm",
      "chatbot", "agent"],
  // Contexte général : poids faible
  1: ["site web", "website", "marketing", "contenu", "content", "branding",
      "mobile", "sécurité", "https", "hébergement", "hosting"],
}

// Fenêtre de fraîcheur : un article de veille sur un sujet de 3 mois ne
// présente aucun intérêt.
const MAX_AGE_DAYS = 14
const now = Date.now()

const scored = []
const seenTitles = new Set()

for (const item of $input.all()) {
  const j = item.json
  const title = (j.title || "").trim()
  const link = (j.link || "").trim()
  if (!title || !link) continue

  // Doublon à l'intérieur du même passage (le même sujet remonte souvent
  // sur plusieurs flux le même jour).
  const fingerprint = title.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim()
  if (seenTitles.has(fingerprint)) continue
  seenTitles.add(fingerprint)

  const dateStr = j.isoDate || j.pubDate || j.date
  const published = dateStr ? new Date(dateStr).getTime() : NaN
  if (!Number.isNaN(published)) {
    const ageDays = (now - published) / 86400000
    if (ageDays > MAX_AGE_DAYS || ageDays < -1) continue
  }

  const haystack = [title, j.contentSnippet || "", (j.categories || []).join(" ")]
    .join(" ")
    .toLowerCase()

  let score = 0
  for (const [weight, words] of Object.entries(KEYWORDS)) {
    for (const word of words) {
      if (haystack.includes(word)) score += Number(weight)
    }
  }

  // En dessous, le sujet est hors niche : on ne dépense pas de tokens dessus.
  if (score < 3) continue

  scored.push({
    json: {
      title,
      link,
      score,
      publishedAt: dateStr || null,
      summary: (j.contentSnippet || "").slice(0, 1200),
      source: (() => { try { return new URL(link).hostname } catch { return "" } })(),
    },
  })
}

// Meilleur score d'abord ; le nœud « Limiter » ne gardera que le premier.
scored.sort((a, b) => b.json.score - a.json.score)
return scored

// La chaîne LLM place l'objet validé par l'analyseur structuré dans `output`.
// Selon la version de n8n et le modèle, il arrive déjà désérialisé ou encore
// sous forme de chaîne.
const raw = $input.first().json
let article = raw.output !== undefined ? raw.output : raw

if (typeof article === "string") {
  const cleaned = article.replace(/^\s*\`\`\`(?:json)?\s*/i, "").replace(/\`\`\`\s*$/, "")
  try {
    article = JSON.parse(cleaned)
  } catch {
    throw new Error("Sortie du modèle illisible : " + String(article).slice(0, 500))
  }
}

if (!article || typeof article !== "object" || !article.content) {
  throw new Error("Sortie du modèle sans champ content : " + JSON.stringify(raw).slice(0, 500))
}

// Le sujet d'origine, récupéré depuis le nœud de scoring.
const topic = $('Choisir le sujet du jour').first().json

// Même si la consigne l'interdit, un modèle encadre parfois son HTML d'un bloc
// de code Markdown. Le webhook rejetterait alors le contenu en 422.
const content = String(article.content)
  .replace(/^\s*\`\`\`(?:html)?\s*/i, "")
  .replace(/\`\`\`\s*$/, "")
  .trim()

// Le site refuse un titre de plus de 160 caractères. Plutôt que de perdre une
// génération entière sur un 422, on coupe sur un mot entier.
let title = String(article.title || "").replace(/\s+/g, " ").trim()
if (title.length > 160) {
  const cut = title.slice(0, 160)
  const lastSpace = cut.lastIndexOf(" ")
  title = (lastSpace > 100 ? cut.slice(0, lastSpace) : cut).trim()
}

// Filet de sécurité sur le slug : la route le régénère depuis le titre s'il est
// absent, mais un slug accentué, espacé ou finissant par un tiret serait rejeté.
const slug = String(article.slug || "")
  .normalize("NFD")
  .replace(/[\u0300-\u036f]/g, "")
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, "-")
  .replace(/(^-|-$)/g, "")
  .slice(0, 120)
  .replace(/-+$/, "")

// Mention de la source, ajoutée hors du texte rédigé : elle rend la veille
// vérifiable au moment de la relecture dans /gestion/blog.
const sourceNote = topic && topic.link
  ? '<hr><p><em>Article inspiré de l\'actualité : <a href="' + topic.link +
    '" target="_blank" rel="noopener noreferrer">' + (topic.title || topic.link) + '</a>' +
    (topic.source ? " (" + topic.source + ")" : "") + '.</em></p>'
  : ""

return [{
  json: {
    title,
    slug: slug || undefined,
    excerpt: String(article.excerpt || "")
      .replace(/<[^>]+>/g, "")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 300),
    content: content + sourceNote,
    tags: Array.isArray(article.tags)
      ? article.tags
          .map((t) => String(t).replace(/\s+/g, " ").trim().slice(0, 40))
          .filter(Boolean)
          .slice(0, 6)
      : [],
    // cover_url : laissé vide ici. Pour une image, ajoute avant ce nœud un
    // appel à Unsplash/Pexels et renseigne cover_url avec une URL https.
  },
}]

// Le nœud « Publier » est configuré en « never error » + « full response » :
// on lit nous-mêmes le code HTTP pour distinguer les cas.
const res = $input.first().json
const status = res.statusCode
const body = res.body || {}
const article = $('Préparer l\'article').first().json

if (status === 201) {
  return [{ json: {
    resultat: "brouillon_cree",
    message: "Brouillon créé. À relire puis publier dans /gestion/blog.",
    titre: article.title,
    slug: body.slug,
    relecture: body.review_url,
  }}]
}

if (status === 409) {
  return [{ json: {
    resultat: "doublon_ignore",
    message: "Un article portant ce slug existe déjà — rien n'a été écrit.",
    titre: article.title,
    slug: body.slug,
  }}]
}

// 401 : secret faux. 422 : le modèle a produit un champ invalide (body.details
// dit lequel). 503 : variables d'environnement manquantes côté site.
throw new Error(
  "Publication refusée (HTTP " + status + ") : " + JSON.stringify(body)
)

